mapper.update:
update financial_raw_data
company_id = #{companyId,jdbcType=INTEGER}, fiscal_year = #{fiscalYear,jdbcType=SMALLINT}, report_period = #{reportPeriod,jdbcType=VARCHAR}, item_id = #{itemId,jdbcType=INTEGER}, amount = #{amount,jdbcType=DECIMAL}, data_source = #{source,jdbcType=VARCHAR}, create_time = #{createTime,jdbcType=TIMESTAMP},
where data_id = #{dataId,jdbcType=BIGINT}

mapper.select:
select r.item_code, r.item_name, r.statement, r.unit, d.amount
from financial_raw_data d
join report_item r on d.item_id = r.item_id
where d.company_id = #{companyId,jdbcType=INTEGER}
  and d.fiscal_year = #{fiscalYear,jdbcType=SMALLINT}
  and d.report_period = #{reportPeriod,jdbcType=VARCHAR}
order by r.display_order

mapper.delete:
delete from financial_raw_data
where company_id = #{companyId,jdbcType=INTEGER}
  and fiscal_year = #{fiscalYear,jdbcType=SMALLINT}
  and report_period = #{reportPeriod,jdbcType=VARCHAR}
